create or replace function preview_schedule_batch_move_v1(p_moves jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare e jsonb;r teacher_schedule%rowtype;n int;ok boolean:=false;msg text;begin perform open_permission_context('schedule.edit');if jsonb_typeof(p_moves)<>'array' or jsonb_array_length(p_moves)=0 or jsonb_array_length(p_moves)>100 then return jsonb_build_object('ok',false,'error','BATCH_SIZE_INVALID');end if;select count(distinct (x->>'schedule_id')::uuid) into n from jsonb_array_elements(p_moves)x;if n<>jsonb_array_length(p_moves) then return jsonb_build_object('ok',false,'error','DUPLICATE_SCHEDULE_ROW');end if;select count(*) into n from teacher_schedule where active and institution_code=current_tenant_code() and not locked and id in(select (x->>'schedule_id')::uuid from jsonb_array_elements(p_moves)x);if n<>jsonb_array_length(p_moves) then return jsonb_build_object('ok',false,'error','SCHEDULE_ROW_NOT_FOUND_OR_LOCKED');end if;begin update teacher_schedule set active=false where id in(select (x->>'schedule_id')::uuid from jsonb_array_elements(p_moves)x);for e in select * from jsonb_array_elements(p_moves) loop select * into r from teacher_schedule where id=(e->>'schedule_id')::uuid and institution_code=current_tenant_code();perform upsert_schedule_slot_permission_core_v2(r.teacher_assignment_id,(e->>'weekday')::smallint,(e->>'period')::smallint,coalesce(nullif(e->>'classroom_id','')::uuid,r.classroom_id),r.subgroup_id,r.id,false,'manual');end loop;ok:=true;raise exception using errcode='P0001',message='OKULOS_PREVIEW_ROLLBACK';exception when others then if SQLERRM='OKULOS_PREVIEW_ROLLBACK' and ok then return jsonb_build_object('ok',true,'count',jsonb_array_length(p_moves));else msg:=SQLERRM;return jsonb_build_object('ok',false,'error',msg);end if;end;end$$;
create or replace function move_schedule_slots_batch_v1(p_moves jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare e jsonb;r teacher_schedule%rowtype;n int;begin perform open_permission_context('schedule.edit');if jsonb_typeof(p_moves)<>'array' or jsonb_array_length(p_moves)=0 or jsonb_array_length(p_moves)>100 then raise exception 'BATCH_SIZE_INVALID';end if;select count(distinct (x->>'schedule_id')::uuid) into n from jsonb_array_elements(p_moves)x;if n<>jsonb_array_length(p_moves) then raise exception 'DUPLICATE_SCHEDULE_ROW';end if;perform 1 from teacher_schedule where active and institution_code=current_tenant_code() and not locked and id in(select (x->>'schedule_id')::uuid from jsonb_array_elements(p_moves)x) for update;select count(*) into n from teacher_schedule where active and institution_code=current_tenant_code() and not locked and id in(select (x->>'schedule_id')::uuid from jsonb_array_elements(p_moves)x);if n<>jsonb_array_length(p_moves) then raise exception 'SCHEDULE_ROW_NOT_FOUND_OR_LOCKED';end if;perform create_schedule_restore_point('Toplu taşıma öncesi','Ders programı güvenli çoklu taşıma geri dönüş noktası');update teacher_schedule set active=false where id in(select (x->>'schedule_id')::uuid from jsonb_array_elements(p_moves)x);for e in select * from jsonb_array_elements(p_moves) loop select * into r from teacher_schedule where id=(e->>'schedule_id')::uuid and institution_code=current_tenant_code();perform upsert_schedule_slot_permission_core_v2(r.teacher_assignment_id,(e->>'weekday')::smallint,(e->>'period')::smallint,coalesce(nullif(e->>'classroom_id','')::uuid,r.classroom_id),r.subgroup_id,r.id,false,'manual');end loop;return jsonb_build_object('ok',true,'count',n);end$$;